def _kx9_win_fold(seq):
    if len(seq) < 2:
        return list(seq)
    return [((seq[i + 1] - seq[i]) % 7) for i in range(len(seq) - 1)]

def _vq4_rle_span(seq):
    if not seq:
        return []
    out = []
    cur = seq[0]
    count = 1
    for v in seq[1:]:
        if v == cur:
            count += 1
        else:
            out.append(cur * count)
            cur = v
            count = 1
    out.append(cur * count)
    return out

def _zm7_zigzag_fold(seq):
    n = len(seq)
    half = n // 2
    if half == 0:
        return list(seq)
    return [seq[i] + seq[n - 1 - i] for i in range(half)]

